  if (!/^[0-9a-f]{40,64}$/.test(expectedSha) || /^0+$/.test(expectedSha)) return false;
  return git(repo.cwd, ["update-ref", "-d", "--end-of-options", `refs/heads/${branch}`, expectedSha], { allowFailure: true }).status === 0;
